<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '../api'
const list=ref([]), purchases=ref([]), loading=ref(false), dialog=ref(false), drawer=ref(false), detail=ref({})
const filters=ref({keyword:'',currentProcess:'',batchStatus:''}), form=ref({id:null,batchNo:'',purchaseOrderId:null,currentProcess:'萎凋',batchStatus:'待加工'})
const steps=['萎凋','杀青','揉捻','烘干'], statuses=['待加工','加工中','已完成']
const purchaseNo=id=>purchases.value.find(x=>x.id===id)?.orderNo||`#${id}`
async function load(){loading.value=true;try{list.value=await api.listBatches(filters.value)}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
function open(row){form.value=row?{...row}:{id:null,batchNo:'',purchaseOrderId:purchases.value[0]?.id,currentProcess:'萎凋',batchStatus:'待加工'};dialog.value=true}
async function save(){try{form.value.id?await api.updateBatch(form.value.id,form.value):await api.createBatch(form.value);dialog.value=false;ElMessage.success('加工批次已保存');await load()}catch(e){ElMessage.error(e.message)}}
async function show(id){detail.value=await api.getBatch(id);drawer.value=true}
onMounted(async()=>{purchases.value=await api.listPurchases();await load()})
</script>
<template><div class="page-card"><div class="toolbar"><div class="filters"><el-input v-model="filters.keyword" clearable placeholder="批次号" style="width:180px"/><el-select v-model="filters.currentProcess" clearable placeholder="全部工序" style="width:130px"><el-option v-for="x in steps" :key="x" :label="x" :value="x"/></el-select><el-select v-model="filters.batchStatus" clearable placeholder="全部状态" style="width:130px"><el-option v-for="x in statuses" :key="x" :label="x" :value="x"/></el-select><el-button @click="load">筛选</el-button></div><el-button type="primary" @click="open()">新增批次</el-button></div><el-table :data="list" v-loading="loading" border stripe><el-table-column prop="batchNo" label="批次号"/><el-table-column label="关联收购单"><template #default="{row}">{{purchaseNo(row.purchaseOrderId)}}</template></el-table-column><el-table-column prop="currentProcess" label="当前工序"/><el-table-column prop="batchStatus" label="批次状态"><template #default="{row}"><el-tag :type="row.batchStatus==='已完成'?'success':row.batchStatus==='加工中'?'warning':'info'">{{row.batchStatus}}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row.id)">详情</el-button><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="form.id?'编辑加工批次':'新增加工批次'" width="500px"><el-form :model="form" label-width="100px"><el-form-item label="批次号"><el-input v-model="form.batchNo"/></el-form-item><el-form-item label="收购单"><el-select v-model="form.purchaseOrderId" style="width:100%"><el-option v-for="x in purchases" :key="x.id" :label="x.orderNo" :value="x.id"/></el-select></el-form-item><el-form-item label="当前工序"><el-select v-model="form.currentProcess" style="width:100%"><el-option v-for="x in steps" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="批次状态"><el-select v-model="form.batchStatus" style="width:100%"><el-option v-for="x in statuses" :key="x" :label="x" :value="x"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-drawer v-model="drawer" title="加工批次详情" size="420px"><dl class="detail-grid"><template v-for="(v,k) in detail" :key="k"><dt>{{k}}</dt><dd>{{v??'-'}}</dd></template></dl></el-drawer></div></template>
